import numpy as np

X = np.array([1.0, 2.0, 3.0, 10.0, 11.0, 12.0, 30.0])

def kmeans_1d(X, centres):
    centres = np.array(centres, dtype=float)
    labels = None
    while True:
        new = np.argmin(np.abs(X[:, None] - centres[None, :]), axis=1)
        for j in range(len(centres)):
            if np.any(new == j):
                centres[j] = X[new == j].mean()
        if labels is not None and np.array_equal(new, labels):
            return new.tolist(), centres.tolist()
        labels = new

for start in ([1, 10, 30], [1, 2, 3]):
    labels, centres = kmeans_1d(X, start)
    inertia = sum((x - centres[l]) ** 2 for x, l in zip(X, labels))
    print(start, labels, centres, round(float(inertia), 2))

