def kmeans(X, init, max_iter=100):
    X = np.array(X, dtype=float)
    C = np.array(init, dtype=float)
    if X.ndim != 2 or len(X) == 0 or C.ndim != 2 or len(C) == 0 or C.shape[1] != X.shape[1] or max_iter < 1:
        raise ValueError('need rows, starting centroids of the same width, and max_iter >= 1')
    labels = None
    for _ in range(max_iter):
        new = assign(X, C)
        for j in range(len(C)):
            members = [i for i in range(len(new)) if new[i] == j]
