import numpy as np

def assign(X, centroids):
    C = np.array(centroids, dtype=float)
    if C.ndim != 2 or len(C) == 0:
        raise ValueError('need at least one centroid')
    X = np.array(X, dtype=float).reshape(-1, C.shape[1])
    return [int(np.argmin(np.sum((C - x) ** 2, axis=1))) for x in X]


def kmeans(X, init, max_iter=100):
    X = np.array(X, dtype=float)
    C = np.array(init, dtype=float)
    if X.ndim != 2 or len(X) == 0 or C.ndim != 2 or len(C) == 0 or C.shape[1] != X.shape[1] or max_iter < 1:
        raise ValueError('need rows, starting centroids of the same width, and max_iter >= 1')
    labels = None
    for _ in range(max_iter):
        new = assign(X, C)
        for j in range(len(C)):
            members = [i for i in range(len(new)) if new[i] == j]
            if members:
                C[j] = X[members].mean(axis=0)
        if new == labels:
            break
        labels = new
    labels = new
    inertia = float(sum(np.sum((X[i] - C[labels[i]]) ** 2) for i in range(len(X))))
    return {'centroids': C.tolist(), 'labels': labels, 'inertia': inertia}
